### S1: Build a university system with courses, students, and grades stored in nested dicts.

```python
university = {
    "CS101": {
        "title":    "Introduction to Python",
        "credits":  3,
        "students": {
            "S001": {"name": "Alice",     "grades": [85, 90, 88, 92]},
            "S002": {"name": "Bob",       "grades": [72, 68, 75, 70]},
            "S003": {"name": "Veerababu", "grades": [95, 98, 93, 97]},
        }
    },
    "CS201": {
        "title":    "Data Structures",
        "credits":  4,
        "students": {
            "S001": {"name": "Alice",  "grades": [88, 82, 90]},
            "S004": {"name": "Carol",  "grades": [65, 70, 68]},
        }
    }
}

def university_report(uni):
    print("=" * 55)
    print("UNIVERSITY ACADEMIC REPORT")
    print("=" * 55)

    all_gpas = {}  # student_name → list of averages across courses

    for course_id, course in uni.items():
        print(f"\n📚 {course_id}: {course['title']} ({course['credits']} credits)")
        print(f"   {'Student':<12} {'Avg':>6} {'Grade':>7} {'Status':>8}")
        print(f"   {'-'*38}")

        course_avgs = []
        for sid, student in course["students"].items():
            avg   = sum(student["grades"]) / len(student["grades"])
            grade = "A" if avg >= 90 else ("B" if avg >= 75 else ("C" if avg >= 60 else "F"))
            status = "✅ Pass" if avg >= 60 else "❌ Fail"

            print(f"   {student['name']:<12} {avg:>6.1f} {grade:>7} {status:>8}")
            course_avgs.append(avg)

            # Accumulate for cross-course GPA
            all_gpas.setdefault(student["name"], []).append(avg)

        course_avg = sum(course_avgs) / len(course_avgs)
        print(f"\n   Course Average: {course_avg:.1f}")

    print("\n=== Overall Student GPA ===")
    for student, avgs in sorted(all_gpas.items(), key=lambda x: sum(x[1])/len(x[1]), reverse=True):
        gpa = sum(avgs) / len(avgs)
        print(f"  {student:<15}: GPA = {gpa:.2f} (across {len(avgs)} courses)")

university_report(university)
```

### S2: Implement a JSON-like configuration system with nested overrides.

```python
import copy

class NestedConfig:
    def __init__(self, defaults):
        self._config = copy.deepcopy(defaults)

    def get(self, *keys, default=None):
        """Navigate nested config safely"""
        current = self._config
        for key in keys:
            if isinstance(current, dict):
                current = current.get(key)
                if current is None:
                    return default
            else:
                return default
        return current

    def set(self, *keys_and_value):
        """Set a nested value: set('db', 'host', 'newhost')"""
        *keys, value = keys_and_value
        current = self._config
        for key in keys[:-1]:
            current = current.setdefault(key, {})
        current[keys[-1]] = value

    def override(self, override_dict):
        """Deep merge override dict into config"""
        def deep_merge(base, over):
            for k, v in over.items():
                if k in base and isinstance(base[k], dict) and isinstance(v, dict):
                    deep_merge(base[k], v)
                else:
                    base[k] = v
        deep_merge(self._config, override_dict)

    def show(self, d=None, indent=0):
        if d is None:
            d = self._config
        for k, v in d.items():
            if isinstance(v, dict):
                print("  " * indent + f"{k}:")
                self.show(v, indent + 1)
            else:
                print("  " * indent + f"{k}: {v}")

# Usage
config = NestedConfig({
    "database": {"host": "localhost", "port": 5432, "name": "dev_db"},
    "app":      {"debug": True, "port": 8000, "workers": 2},
    "cache":    {"ttl": 300, "max_size": 1000}
})

# Override for production
config.override({
    "database": {"host": "prod-db.company.com", "name": "prod_db"},
    "app":      {"debug": False, "workers": 8}
})

# Set individual values
config.set("app", "version", "2.1.0")

print("=== Final Configuration ===")
config.show()
print(f"\nDB Host: {config.get('database', 'host')}")
print(f"Workers: {config.get('app', 'workers')}")
print(f"Missing: {config.get('app', 'missing_key', default='N/A')}")
```

### S3: Process a nested employee hierarchy to find reporting chains.

```python
# Organization hierarchy: manager → {info, reports: [employee_ids]}
org = {
    "CEO001": {
        "name": "Sarah Chen",
        "title": "CEO",
        "salary": 500000,
        "reports": ["VP001", "VP002"]
    },
    "VP001": {
        "name": "James Wilson",
        "title": "VP Engineering",
        "salary": 300000,
        "reports": ["MGR001", "MGR002"]
    },
    "VP002": {
        "name": "Lisa Park",
        "title": "VP Marketing",
        "salary": 280000,
        "reports": ["MGR003"]
    },
    "MGR001": {
        "name": "Alice",
        "title": "Eng Manager",
        "salary": 180000,
        "reports": ["E001", "E002"]
    },
    "MGR002": {
        "name": "Bob",
        "title": "DevOps Manager",
        "salary": 170000,
        "reports": ["E003"]
    },
    "MGR003": {
        "name": "Carol",
        "title": "Marketing Manager",
        "salary": 160000,
        "reports": []
    },
    "E001": {"name": "Veerababu", "title": "Senior Dev",     "salary": 95000,  "reports": []},
    "E002": {"name": "Dave",      "title": "Developer",      "salary": 80000,  "reports": []},
    "E003": {"name": "Eve",       "title": "DevOps Engineer","salary": 85000,  "reports": []},
}

def get_total_team_size(emp_id, org_chart):
    """Recursively count all reports under an employee"""
    reports = org_chart[emp_id]["reports"]
    if not reports:
        return 0
    total = len(reports)
    for report_id in reports:
        total += get_total_team_size(report_id, org_chart)
    return total

def get_reporting_chain(emp_id, org_chart):
    """Find all managers above an employee"""
    chain = []
    for manager_id, manager in org_chart.items():
        if emp_id in manager.get("reports", []):
            chain.append(manager["name"])
            chain.extend(get_reporting_chain(manager_id, org_chart))
    return chain

def total_salary_under(emp_id, org_chart):
    """Sum of all salaries in a subtree"""
    reports = org_chart[emp_id]["reports"]
    total   = org_chart[emp_id]["salary"]
    for rid in reports:
        total += total_salary_under(rid, org_chart)
    return total

# Report
print("=== Organization Report ===\n")
for emp_id, emp in org.items():
    team_size  = get_total_team_size(emp_id, org)
    chain      = get_reporting_chain(emp_id, org)
    total_cost = total_salary_under(emp_id, org)

    print(f"[{emp_id}] {emp['name']} — {emp['title']}")
    print(f"   Direct reports:  {len(emp['reports'])}")
    print(f"   Total team:      {team_size}")
    print(f"   Reports to:      {' → '.join(chain) if chain else 'Nobody (Top Level)'}")
    print(f"   Team salary cost:₹{total_cost:,}")
    print()
