        "Gulab Jamun":   {"price": 120, "veg": True,  "spicy": False},
        "Ice Cream":     {"price": 100, "veg": True,  "spicy": False},
    }
}

def filter_menu(menu, veg_only=False, max_price=None):
    """Filter menu based on preferences"""
    filtered = {}
    for category, items in menu.items():
        filtered_items = {}
        for item, details in items.items():
            if veg_only and not details["veg"]:
                continue
            if max_price and details["price"] > max_price:
                continue
            filtered_items[item] = details
        if filtered_items:
            filtered[category] = filtered_items
    return filtered

# Get veg menu under ₹250
