### S1: Merge user profiles from 3 microservices — auth, profile, and subscription.

```python
# Three separate service responses for the same user
auth_data = {
    "user_id": "U001",
    "email":   "alice@example.com",
    "role":    "premium_user",
    "mfa":     True
}

profile_data = {
    "user_id":   "U001",      # Common key — same value (OK)
    "first_name": "Alice",
    "last_name":  "Smith",
    "age":        28,
    "city":       "Hyderabad",
    "avatar":     "https://cdn.example.com/alice.jpg"
}

subscription_data = {
    "user_id":     "U001",    # Common key — same value (OK)
    "plan":        "Pro",
    "billing":     "monthly",
    "expires":     "2026-12-31",
    "api_calls":   {"used": 4523, "limit": 10000}
}

def merge_user_services(auth, profile, subscription):
    """
    Merge data from multiple services.
    Shared keys (like user_id) should be identical — validate!
    """
    # Validate shared keys are consistent
    shared_key = "user_id"
    ids = {auth.get(shared_key), profile.get(shared_key), subscription.get(shared_key)}
    ids.discard(None)
    if len(ids) > 1:
        raise ValueError(f"Conflicting user IDs across services: {ids}")

    # Merge — later services override earlier for any conflicts
    merged = {**auth, **profile, **subscription}

    # Add computed fields
    merged["full_name"]   = f"{merged.get('first_name','')} {merged.get('last_name','')}".strip()
    merged["api_usage_pct"] = round(
        merged["api_calls"]["used"] / merged["api_calls"]["limit"] * 100, 1
    )

    return merged

user = merge_user_services(auth_data, profile_data, subscription_data)
print("=== Merged User Profile ===")
for key, value in user.items():
    print(f"  {key:<18}: {value}")
