### S2: Implement a smart merge function that handles type conflicts gracefully.

```python
def smart_merge(*dicts, conflict_strategy="last_wins"):
    """
    Merge multiple dicts with configurable conflict resolution.

    Strategies:
    - "last_wins":  last dict's value wins (default)
    - "first_wins": first dict's value wins
    - "sum":        sum numeric values, concatenate strings/lists
    - "max":        keep maximum value (for comparables)
    - "min":        keep minimum value (for comparables)
    """
    result = {}

    for d in dicts:
        for key, value in d.items():
            if key not in result:
                result[key] = value   # First occurrence — always keep
                continue

            existing = result[key]

            if conflict_strategy == "last_wins":
                result[key] = value

            elif conflict_strategy == "first_wins":
                pass  # Keep existing (first)

            elif conflict_strategy == "sum":
                if isinstance(existing, (int, float)) and isinstance(value, (int, float)):
                    result[key] = existing + value
                elif isinstance(existing, list) and isinstance(value, list):
                    result[key] = existing + value
                elif isinstance(existing, str) and isinstance(value, str):
                    result[key] = existing + " " + value
                else:
                    result[key] = value  # Fallback

            elif conflict_strategy == "max":
                try:
                    result[key] = max(existing, value)
                except TypeError:
                    result[key] = value

            elif conflict_strategy == "min":
                try:
                    result[key] = min(existing, value)
                except TypeError:
                    result[key] = existing

    return result

# Test all strategies
d1 = {"revenue": 50000, "name": "Alice",   "tags": ["python", "sql"]}
d2 = {"revenue": 75000, "name": "Bob",     "tags": ["java", "spring"]}
d3 = {"revenue": 60000, "name": "Veerababu","tags": ["ml", "ai"]}

for strategy in ["last_wins", "first_wins", "sum", "max", "min"]:
    merged = smart_merge(d1, d2, d3, conflict_strategy=strategy)
    print(f"\nStrategy '{strategy}':")
    print(f"  revenue: {merged['revenue']}")
    print(f"  name:    {merged['name']}")
    print(f"  tags:    {merged['tags']}")
```

